boolean[][] visited;
public int numIslands(char[][] grid) {
    int ans = 0;
    int m = grid.length;
    if (m == 0) {
        return ans;
    }
    int n = grid[0].length;
    visited = new boolean[m][n];
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (!visited[i][j] && dfs(grid, i, j)) {
                ans++;
            }
        }
    }
    return ans;
}

private boolean dfs(char[][] grid, int i, int j) {
    if (i < 0 || j < 0 || i >= grid.length || j >= grid[0].length) {
        return false;
    }
    if (visited[i][j]) {
        return false;
    }
    visited[i][j] = true;
    if (grid[i][j] == '0') {
        return false;
    }
    boolean has = true;
    has |= dfs(grid, i + 1, j);
    has |= dfs(grid, i - 1, j);
    has |= dfs(grid, i, j + 1);
    has |= dfs(grid, i, j - 1);
    return has;
}

